import * as React from "react";
import { View, Text, Image, StyleSheet } from "react-native";

export function DateDisplay({ date }) {
  return (
    <View style={styles.dateContainer}>
      <View style={styles.dateWrapper}>
        <Image
          resizeMode="contain"
          source={{ uri: "https://cdn.builder.io/api/v1/image/assets/TEMP/f6d4955931c2ba7bfbe41cb0a98257a30eeb33a52eae7293bdc8ece23018ee3c?placeholderIfAbsent=true&apiKey=6d0c12d1b41b41cabcfc21945748b772" }}
          style={styles.dateIcon}
        />
        <View style={styles.dateTextContainer}>
          <Text style={styles.dateText}>{date}</Text>
        </View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  dateContainer: {
    display: "flex",
    marginTop: 16,
    width: "100%",
    alignItems: "center",
    gap: 34,
  },
  dateWrapper: {
    alignSelf: "stretch",
    display: "flex",
    marginVertical: "auto",
    alignItems: "center",
    flexDirection: "row",
    gap: 4,
  },
  dateIcon: {
    width: 18,
    aspectRatio: 1,
  },
  dateTextContainer: {
    alignSelf: "stretch",
    marginVertical: "auto",
  },
  dateText: {
    color: "#1D1D1D",
    fontSize: 12,
  },
});
